namespace ghidra.pcode.emu.unix;



using ghidra.pcode.emu.sys;

/**
 * An abstract emulated file system, exported to an emulated user-space program
 *
 * @param <T> the type of values stored in the file system
 */
public abstract class AbstractEmuUnixFileSystem<T> : EmuUnixFileSystem<T> {
	protected Map<string, EmuUnixFile<T>> filesByPath = new();

	/* @Override */
	public abstract AbstractEmuUnixFile<T> newFile(string pathname, int mode);

	/* @Override */
	public EmuUnixFile<T> createOrGetFile(string pathname, int mode)
    {
		return filesByPath.computeIfAbsent(pathname, p => newFile(p, mode));
	}

	/* @Override */
	public EmuUnixFile<T> getFile(string pathname)
    {
		return filesByPath.get(pathname);
	}

	/* @Override */
	public void putFile(string pathname, EmuUnixFile<T> file)
    {
		filesByPath.put(pathname, file);
	}

	/* @Override */
	public EmuUnixFile<T> open(string pathname, Set<OpenFlag> flags, EmuUnixUser user,
			int mode)
    {
		EmuUnixFile<T> file =
			flags.contains(OpenFlag.O_CREAT) ? createOrGetFile(pathname, mode) : getFile(pathname);

		if (file == null) {
			throw new EmuIOException("File not found: " + pathname);
		}
		if (flags.contains(OpenFlag.O_RDONLY) || flags.contains(OpenFlag.O_RDWR)) {
			file.checkReadable(user);
		}
		if (flags.contains(OpenFlag.O_WRONLY) || flags.contains(OpenFlag.O_RDWR)) {
			file.checkWritable(user);
			if (flags.contains(OpenFlag.O_TRUNC)) {
				file.truncate();
			}
		}
		return file;
	}

	/* @Override */
	public void unlink(string pathname, EmuUnixUser user)
    {
		filesByPath.remove(pathname);
	}
}
